function findCombinationSum(array, target) { 
  for (let i = 0; i < Math.pow(2, array.length); i++) { 
    let sum = 0; 
    let current = i; 
    let output = []; 

    array.forEach(function(item, index) { 
      if (current & 1) { 
        output.push(item); 
        sum += item;
      }
      current = current >> 1; 
    });

    if (sum === target) { 
        console.log(output); 
    }
  }
}

