class Dictionary:
    def __init__(self):
        self.dict = dict()

    def insert(self, key, value):
        self.dict[key] = value

    def find(self, key):
        if key in self.dict:
            return self.dict[key]
        else:
            return None

    def delete(self, key):
        if key in self.dict:
            del self.dict[key]
            return True
        else:
            return False

    def update(self, key, value):
        if key in self.dict:
            self.dict[key] = value
            return True
        else:
