function isValidIPV4(str) {
    const ipv4_Octets = str.split(".");
    if (ipv4_Octets.length !== 4) {
        return false;
    }
    for (let octet of ipv4_Octets) {
        if (octet.length === 0 || octet.length > 3) {
            return false;
        }
        if (isNaN(octet) || octet < 0 || octet > 255) {
            return false;
        }
        if (octet[0] === '0' && octet.length != 1) {
            return false;
        }
    }
    return true;
}

