class HashTable:
    def __init__(self):
        self.table = [[] for i in range(256)]

    def get(self, key):
        hash_value = self._hash_function(key)
        bucket = self.table[hash_value]
        for (k,v) in bucket:
            if k == key:
                return v
        return None

    def put(self, key, value):
        hash_value = self._hash_function(key)
        bucket = self.table[hash_value]
        found = False
        for i, kv in enumerate(bucket):
            k, v = kv
            if key == k:
                found = True
                break
        if not found:
            bucket.append( (key,value) )
        else:
            bucket[i] = ( (key,value) ) 

    def _hash_function(self, key):
        return hash(str(key)) & 0xFF

