public class NumberEncoder {

    // Helper function to check if a character 
    // is part of the given set of characters
    public static boolean isValidChar(char c) {
        return (c >= 'A' && c <= 'Z') 
        || (c >= 'a' && c <= 'z') 
        || (c >= '0' && c <= '9');
    }

    // Function to encode a given number 
    // into a string such that only 
    // characters from the given set of  
    // characters can be used 
    public static String encodeNumber(int num) {
        // Store the result in this string
        String str = ""; 

        // Iterate while num is not equal to 0 
        while (num > 0) { 
            // Find the character to append
            char c = (char)(num % 62); 

            // Check if the character is valid or not
            if (isValidChar(c))  
                str += c; 
            else 
                str += 'A'; 

            // Update num
            num /= 62; 
        } 

        // Reverse the string 
        return new StringBuilder(str).reverse().toString(); 
    } 

    // Driver Program 
    public static void main(String[] args) {
        int num = 12345; 
        System.out.println(encodeNumber(num)); 
    } 
}

