class HashTable:
    def __init__(self, size):
        self.size = size
        self.table = [[] for _ in range(self.size)]

    def _get_hash_val(self, key):
        hash_val = 0
        for char in key:
            hash_val += ord(char)
        return hash_val%self.size

    def set(self, key, value):
        hash_val = self._get_hash_val(key)
        key_exists = False
        bucket = self.table[hash_val]
        for i, kv in enumerate(bucket):
            k, v = kv
            if key == k:
                key_exists = True
                break
        if key_exists:
            bucket[i] = ((key, value))
        else:
            bucket.append((key, value))

    def get(self, key):
        hash_val = self._get_hash_val(key)
        bucket = self.table[hash_val]
        for i, kv in enumerate(bucket):
            k, v = kv
            if key == k:
                return v
        return None

