def subsets(nums, k):
  result = []
  def backtrack(subset, start):
    if len(subset) == k:
      result.append(subset)
      return

    for i in range(start, len(nums)):
      subset.append(nums[i])
      backtrack(subset, i+1)
      subset.pop()
  backtrack([], 0)
  return len(result)

