        self.next = None


class LinkedList: 
    def __init__(self): 
        self.head = None

    def printList(self): 
        temp = self.head 
        while (temp): 
            print (temp.data) 
            temp = temp.next

    def insertAtBeginning(self, new_data):  
        new_node = Node(new_data) 
        new_node.next = self.head 
        self.head = new_node 

    def insertAtEnd(self, new_data):
        if self.head is None:
            self.head = Node(new_data)
            return 
        last = self.head
        while(last.next):
            last = last.next
        last.next = Node(new_data)

    def insertAfter(self, prev_node, new_data): 
        if prev_node is None: 
            print("Previous node should be in the linked list.")
            return
        new_node = Node(new_data) 
        new_node.next = prev_node.next
        prev_node.next = new_node 

    def deleteNode(self, data):
        temp = self.head 
        if (temp == None):
            return  
        if (temp.data == data):
            self.head = temp.next
            temp = None
            return  
        while (temp != None):
            if temp.data == data:  
                break  
            prev = temp
            temp = temp.next
        if (temp == None):
            return  
        prev.next = temp.next
        temp = None


