class Tree:
  def __init__(self, data):
    self.data = data
    self.left = None
    self.right = None

def construct_tree(arr):
  if not arr:
    return None

  root = Tree(arr[0])
  l = 1
  r = len(arr)-1

  while (l<=r): 
    while (l<=r and arr[l]<arr[0]): 
      l += 1
    while (l<=r and arr[r]>arr[0]): 
      r -= 1
    if (l<=r): 
      node = Tree(arr[l])
      root.left = node
      node = Tree(arr[r])
      root.right = node
      l += 1
      r -= 1
  l = 1
  r = len(arr)-1
  construct_tree_util(arr, root, l, r)
  return root 

def construct_tree_util(arr, root, l, r): 
  if (l<r): 
    if (root.data>arr[l]):
      node = Tree(arr[l])
      root.left = node
      construct_tree_util(arr, root.left, l+1, r)
    if (root.data<arr[r]): 
      node = Tree(arr[r])
      root.right = node
      construct_tree_util(arr, root.right, l, r-1)

