import numpy as np 

# Decision Tree classifier 
class DecisionTreeClassifier: 
    # Decision tree node 
    class DecisionTreeNode: 
        def __init__(self, data, depth, attribute): 
            self.data = data 
            self.depth = depth 
            self.attribute = attribute 
            self.num_samples = None 
            self.predicted_class = None
            self.children = [] 

        def get_prediction(self): 
            return self.predicted_class 

        def set_prediction(self, classification): 
            self.predicted_class = classification 

    # Constructor  
    def __init__(self, max_depth): 
        self.max_depth = max_depth 

    # Train the model 
    def fit(self, data): 
        self.tree = self.DecisionTreeNode(data, 0, None) 
        self.build_tree(self.tree) 

    def getMaxGain(self, data): 
        info_gain = {} 
        max_gain = {'information_gain': 0, 'attribute': None} 
        for i in range(data.shape[1]): 
            #Skip the empty columns 
            if data[0][i] == '?': 
                continue  
            info_gain[i] = self.calculateGain(data, i) 
            if info_gain[i] > max_gain['information_gain']: 
                max_gain['information_gain'] = info_gain[i] 
                max_gain['attribute'] = i 
        return max_gain 

    # Split the data based on the given attribute 
    def splitData(self, data, attribute): 
        data_splits = [] 
        unique_values = np.unique(data[:, attribute]) 

        # Create a subset of the data for each unique value 
        # of the given attribute 
        for value in unique_values: 
            subset = data[np.where(data[:, attribute] == value)] 
            data_splits.append(subset) 
        return data_splits 

    def calculateGain(self, data, attribute): 
        info_gain = self.calculateEntropy(data) 
        for subset in self.splitData(data, attribute): 
            info_gain -= float(subset.shape[0]) / float(data.shape[0]) * self.calculateEntropy(subset) 
        return info_gain 

    def calculateEntropy(self, data): 
        labels, counts = np.unique(data[:, data.shape[1] - 1], return_counts = True) 
        entropy = 0 
        for count in counts: 
            entropy += -float(count) / float(data.shape[0]) * np.log2(float(count) / float(data.shape[0])) 
        return entropy 

    #Train the tree 
    def build_tree(self, node): 
        classes, count_classes = np.unique(node.data[:, node.data.shape[1] - 1], return_counts = True) 
        #Check if all samples belong to the same class 
        if count_classes.shape[0] == 1: 
            node.predicted_class = classes[0] 
            node.num_samples = count_classes[0] 
            return 
        #Check if the max_depth is reached 
        if node.depth == self.max_depth: 
            node.predicted_class = self.predictClass(classes, count_classes) 
            node.num_samples = node.data.shape[0] 
            return 
        attr = self.getMaxGain(node.data)['attribute'] 
        #Check if the best attribute has negative information gain
        if attr == None: 
            node.predicted_class = self.predictClass(classes, count_classes) 
            node.num_samples = node.data.shape[0] 
            return
        node.attribute = attr 
        # Split the data based on the best attribute 
        splits = self.splitData(node.data, attr) 
        node.num_samples = node.data.shape[0] 
        # Create the children nodes 
        for subset in splits: 
            c = self.DecisionTreeNode(subset, node.depth + 1, None) 
            node.children.append(c) 
        # Train the children node 
        for c in node.children: 
            self.build_tree(c)  

    # Predict using the tree 
    def predict(self, tree, instance): 
        #Classify the instance 
        if tree.predicted_class != None: 
            return tree.predicted_class 
        #Use the attribute of the node to split  
        attr = tree.attribute 
        #Find the split value of the instance 
        value = instance[attr] 
        #Reach the right branch of the tree 
        for c in tree.children: 
            if c.data[0][attr] == value: 
                return self.predict(c, instance) 

    # Major class for the prediction 
    def predictClass(self, classes, count_classes): 
        return classes[np.argmax(count_classes)]

