def rotate(arr, k):
    n = len(arr)
    temp = []
    for i in range(k):
        temp.append(arr[i])
    for i in range(k, n):
        arr[i - k] = arr[i]
    for i in range(k):
        arr[n - k + i] = temp[i]
    return arr

