def longest_common_prefix(arr):
    n = len(arr)
    if n < 1:
        return ""
    # Find the string with the minimum length
    min_length = len(arr[0])
    min_str = arr[0]
    for s in arr:
        if len(s) < min_length:
            min_length = len(s)
            min_str = s

    # Iterate over the string to find the longest common prefix
    prefix = ""
    for i in range(min_length):
        c = min_str[i]
        all_match = True
        for s in arr:
            if s[i] != c:
                all_match = False
                break
        if all_match:
            prefix += c
        else:
            break
    return prefix

