def median(arr):
    # flatten the array
    flat_arr=[]
    for sublist in arr:
        for val in sublist:
            flat_arr.append(val)

    # sort the array
    flat_arr.sort()

    # get the middle value
    if len(flat_arr) % 2 != 0:
        return flat_arr[len(flat_arr)//2]
    else:
        return (flat_arr[len(flat_arr)//2] + flat_arr[len(flat_arr)//2 - 1])/2

def max_z(x, y):
    if x + y > 10: 
        return 0 

    z = 2*x + y
    step_size = 0.01

    while True: 
        if x + y > 10: 
            break
        dx = step_size
        dy = step_size
        new_z = 2*(x+dx) + (y+dy)
        if new_z > z: 
            x += dx
            y += dy
            z = new_z
        else: 
            break
    return z

