def getMedianFromArray(array):
    # Sort the array using an O(nlog(n)) time complexity
    array.sort()
    n = len(array)
    if n % 2 == 0:
        # If the array has even number of elements:
        return (array[n // 2] + array[n // 2 - 1]) / 2
    else:
        # If the array has odd number of elements:
        return array[n // 2]

