    character_count = {}

    # Loop over each character in the string
    for char in string:
        # Check if a character is in the dictionary
        if char in character_count:
            # Increase the count
            character_count[char] += 1
        else:
            # Initiate the count of the character
            character_count[char] = 1

    # Loop over each character to find the first non-repeating character
