def swap_pairs(head):
    ptr1 = head
    if ptr1 is None:
        return ptr1
    ptr2 = ptr1.next
    if ptr2 is None:
        return ptr1
    ptr3 = send_node(ptr2.next)
    head = ptr2
    ptr2.next = ptr1
    ptr1.next = ptr3
    prev_node = ptr1
    ptr1 = ptr3
    if ptr1 is not None:
        ptr2 = ptr3.next
    while (ptr1 is not None) and (ptr2 is not None):
        ptr3 = send_node(ptr2.next)
        prev_node.next = ptr2
        ptr2.next = ptr1
        ptr1.next = ptr3
        prev_node = ptr1
        ptr1 = ptr3
        if ptr1 is not None:
            ptr2 = ptr3.next
    return head

