def prime_factorization(n):
    ans = []
    i = 2
    while i*i <= n:
        if n % i == 0:
            cnt = 0
            while n % i == 0:
                cnt += 1
                n /= i
            ans.append((i, cnt))
        i += 1
    # when n is a prime
    if n != 1:
        ans.append((n, 1))
    return ans

