public class SerializeBinaryTree {

    private static int index = 0;

    public static String serializeTree(Node root) {
        if (root == null)
            return "null,";
        String data = root.data + ",";
        data += serializeTree(root.left);
        data += serializeTree(root.right);
        return data;
    }

    public static Node deserializeTree(String data) {
        if (data.length() == 0 || data.equals("null,"))
            return null;
        String[] dataString = data.split(",");
        Node root = new Node(Integer.parseInt(dataString[index]));
        index++;
        root.left = deserializeTree(data);
        root.right = deserializeTree(data);
        return root;
    }

    public static void main(String[] args) {
        String data = serializeTree(root);
        Node newRoot = deserializeTree(data);
    }
}

