def max_subarray_sum(arr, k): 

    max_sum = 0; 
    n = len(arr); 

    if (n < k): 
        return; 

    for i in range(n - k + 1): 
        window_sum = 0; 
        for j in range(k): 
            window_sum = window_sum + arr[i+j]; 

        max_sum = max(max_sum, window_sum); 

    return max_sum;

