def generate_maze(row, col): 
    # Create a two dimensional array 
    # filled with 1 to make all walls  
    maze = [[1 for i in range(col)] for j in range(row)] 

    # Choose a random edge to delete
    for i in range(row):
        for j in range(col):
            if j == 0 and i != 0 and i != row - 1:
                maze[i][j] = 0
            elif j == col - 1 and i != 0 and i != row - 1:
                maze[i][j] = 0
            elif i == 0 and j != 0 and j != col - 1:
