def breadth_first_search(graph, start, goal):
    explored = []
    queue = [start]
    while queue:
        node = queue.pop(0)
        if node not in explored:
            explored.append(node)
            neighbours = graph[node]
            for neighbour in neighbours:
                if neighbour == goal:
                    return explored
                else:
                    queue.append(neighbour)
    return False

def hill_climbing(start_state, evaluate_fn):
  current = start_state
  best_state = current
  best_score = evaluate_fn(current)

  while True:
    neighbors = find_neighbors(current)
    for n in neighbors:
      score = evaluate_fn(n)
      if score > best_score:
        best_score = score
        best_state = n

    if best_score <= evaluate_fn(current):    
      break
    current = best_state

  return current

