public ListNode convertToLinkedList(TreeNode root) { 

    // Base case 
    if (root == null) 
        return null; 

    // Initialize result List 
    ListNode result = null; 

    // The main function that flattens a BST into a list 
    flatten(root, result); 

    // returns the root of the 
    //  flattened linked list 
    return result; 
} 

private ListNode flatten(TreeNode root, ListNode list) { 

    // Base cases 
    if (root == null) { 
        return list; 
    } 

    // Step 1. Connect the left and right subtrees 
    list = flatten(root.right, list); 

    // Step 2. Flatten the left subtree 
    list = flatten(root.left, list); 

    // Step 3. Connect sibilings  
    root.right = list; 
    root.left = null; 
    list = root; 

    // return tail of the list 
    return list; 
}

