def bubble_sort(nums):
    '''Takes in a list of numbers and sorts them in ascending order using bubble sort'''
    # Iterate through all numbers 
    for i in range(len(nums)): 

       # Last i elements are already in place 
       for j in range(0, len(nums)-i-1): 

           # Swap numbers if the element is greater than the next element 
           if nums[j] > nums[j+1] : 
               nums[j], nums[j+1] = nums[j+1], nums[j] 

    return nums

