public class MinimumSwapsToMakeEvenOddConsecutive {
    public static int minSwaps(int[] arr) 
    { 
        // Count all even and odd numbers in the array 
        int evenCount = 0, oddCount = 0; 
        for (int i = 0; i < arr.length; i++) { 
            if (arr[i] % 2 == 0) 
                evenCount++; 
            else
                oddCount++; 
        } 
        // If we are unable to match odd and even 
        // after swapping, return -1 
        if (evenCount != oddCount) 
            return -1; 
        // Initialize the count to 0 
        int count = 0; 
        for (int i = 0; i < arr.length;) { 
            // If the current element is even, then find 
            // the next element which is odd 
            if (arr[i] % 2 != 0) { 
                i++; 
                continue; 
            } 
            // If the current element is odd, then find 
            // the next element which is even 
            else { 
                while (arr[i] % 2 == 0) 
                    i++; 
                // Swap them 
                int temp = arr[i]; 
                arr[i] = arr[i - 1]; 
                arr[i - 1] = temp; 
                count++; 
            } 
        } 

        // Return the count 
        return count; 
    } 

    public static void main(String[] args) {
        int[] arr = {3, 5, 7, 4, 8, 6};
        System.out.println("Minimum Swaps Required:\n" + minSwaps(arr));
    }

}

