function getPermutations(str) {
    const permutations = [];

    if (str.length === 1) {
        permutations.push(str);
        return permutations;
    }

    for (let i = 0; i < str.length; i++) {
        const char = str[i];
        const remainingString = str.substring(0, i) + str.substring(i + 1);

        const innerPermutations = getPermutations(remainingString);

        for (let j = 0; j < innerPermutations.length; j++) {
            const newPermutations =
                char + innerPermutations[j];
            permutations.push(newPermutations)
        }
    }
    return permutations;
}
