// Returns the distance between two points with given coordinates
double getDistance(pair <int, int> pointA, pair <int, int> pointB) 
{ 
    return sqrt((pointA.first - pointB.first)*(pointA.first - pointB.first) + 
        (pointA.second - pointB.second)*(pointA.second - pointB.second)); 
} 

// This function finds the closest pair of points in the given array
pair <int, int> closestPair(pair <int, int> points[], int n) 
{ 
    // Minimum Distance
    double minDist = getDistance(points[0], points[1]); 

    // Result 
    pair <int, int> closestPair; 
    closestPair = points[0]; 

    // Loop through all the points
    for (int i = 0; i < n - 1; i++) { 
        for (int j = i + 1; j < n; j++) { 
            double newDist = getDistance(points[i], points[j]); 

            // If the new distance is less, then update the minimum distance
            // and the result also
            if (newDist < minDist) { 
                minDist = newDist; 
                closestPair = make_pair(points[i], points[j]); 
            } 
        } 
    }  

    return minDist; 
} 

