# Function to find the minimum depth of the binary tree
def findMinDepth(root):
    # Base case 1
    if root is None:
        return 0

    # Base case 2
    if (root.left is None) and (root.right is None):
        return 1

    # if left is None, recur for the right node
    if root.left is None:
        return findMinDepth(root.right) + 1

    # If right is None, recur for the left node
    if root.right is None:
        return findMinDepth(root.left) + 1

    # If both left & right are not None, check both left & right
    return min(findMinDepth(root.left),
               findMinDepth(root.right)) + 1

