def quick_sort(arr):
    # Terminating condition
    if len(arr) < 2:
        return arr

    # Select a pivot
    pivot = arr[len(arr) // 2]

    # Partition the array
    left, right = [], []
    for num in arr:
        if num < pivot:
            left.append(num)
        else:
            right.append(num)

    # Recurse
    return quick_sort(left) + [pivot] + quick_sort(right)


