function shuffle(arr) {
    let currIndex = arr.length;
    while (currIndex > 0) {
        const randomIndex = Math.floor(Math.random() * currIndex);
        currIndex--;
        // swap elements
        const temp = arr[currIndex];
        arr[currIndex] = arr[randomIndex];
        arr[randomIndex] = temp;
    }
    return arr;
}

