public class Solution {

    public static int solution(int[] A) {

        int sum = 0;
        int MAX = A.length;

        if(MAX < 256) {
            for(int i = 0; i < MAX; i++) {
                sum += A[i];
            }
        }
        else {
            int mid = MAX / 2;
            int[] B = new int[mid];
            int[] C = new int[MAX - mid];

            for(int i = 0; i < mid; i++) {
                B[i] = A[i];
            }
            for(int i = mid; i < MAX; i++) {
                C[i - mid] = A[i];
            }

            sum = solution(B) + solution(C);
        }
        return sum;
    }
}

