def encrypt(string): 
    result = "" 
    for i in range(len(string)): 
        char = string[i] 

        # Encrypt uppercase characters 
        if (char.isupper()): 
            result += chr((ord(char) + 3 - 65) % 26 + 65) 

        # Encrypt lowercase characters 
        else: 
            result += chr((ord(char) + 3 - 97) % 26 + 97) 

    return result

