def permutations(nums):
    if len(nums) == 0:
        return [ ]
    if len(nums) == 1:
        return [nums]
    permutations = []
    for i in range(len(nums)):
        element = nums[i]
        remaining_elements = [x for x in nums if x != element]
        z = permutations(remaining_elements)  
        for t in z:
            permutations.append([element] + t)
    return permutations

