def has_subset_sum(nums, k):
    n = len(nums)
    dp = [[False] * (k + 1)] * (n + 1)

    # base cases
    for i in range(n + 1):
        dp[i][0] = True
    for j in range(1, k + 1):
        dp[0][j] = False

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if nums[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = (dp[i - 1][j] or
                            dp[i - 1][j - nums[i - 1]])

    return dp[n][k]

