vector<int> longestIncreasingSubsequence(vector<int> array) {
	int n = array.size();
	vector<int> lis(n);

	lis[0] = 1; 

	// Compute LIS values in bottom up manner 
	for (int i = 1; i < n; i++) { 
		for (int j = 0; j < i; j++) { 
			if (array[i] > array[j] && lis[i] < lis[j] + 1) {
				lis[i] = lis[j] + 1; 
			}
		} 
	} 

	// find the longest subsequence 
	int max_val = INT_MIN; 
	for (int i=0; i<n; i++) { 
		if (max_val < lis[i])  
			max_val = lis[i]; 
	} 

	// tracing the LIS
	vector<int> longest_subsequence; 

	int temp = max_val; 
	int count = n-1; 
	while (1) { 
		if (lis[count] == temp) { 
			longest_subsequence.push_back(array[count]); 
			temp--;
			// if temp becomes zero, break from the loop 
			if (temp == 0) 
				break; 
		} 
		count--; 
	}

	return longest_subsequence;
} 

