"""
Design an algorithm to order a deck of 52 playing cards
"""

# Step 1: Create empty array to serve as the ordered deck
ordered_deck = []

# Step 2: Create Helper function for suit ordering
def suit_ordering(suit): 
    # Set suits in order of spades, hearts, diamonds, clubs
    if suit == 'Spades':  
        return 1
    elif suit == 'Hearts':
        return 2
    elif suit == 'Diamonds':
        return 3
    elif suit == 'Clubs':
        return 4

# Step 3: Create Helper function for card numerical ordering
def card_ordering(number):  
    # Set value in order (ace - king)
    # Ace being highest value
    if number == 'Ace':
        return 14
    elif number == '2':
        return 2
    elif number == '3':
        return 3
    elif number == '4':
        return 4
    elif number == '5':
        return 5
    elif number == '6':
        return 6
    elif number == '7':
        return 7
    elif number == '8':
        return 8
    elif number == '9':
        return 9
    elif number == '10': 
        return 10
    elif number == 'Jack':
        return 11
    elif number == 'Queen':
        return 12
    elif number == 'King':
        return 13

# Step 4: Create main function using the helper functions
def order_deck(deck):

    # Loopthrough the deck
    for card in deck:
        # Unpack card values
        number, suit = card
        # Use helper functions to get numerical value of card
        card_value = card_ordering(number)
        suit_value = suit_ordering(suit)
        # Append numerical value to ordered_deck
        ordered_deck.append((card_value, suit_value))

    # Sort ordered_deck by numerical value
    ordered_deck.sort(reverse = True)
    # Return ordered_deck 
    return ordered_deck

