    public static Node create_node(int i, Node root) {
        if (root == null) 
            return new Node(i);  
        if (i < root.data) 
            root.left  = create_node(i, root.left); 
        else if (i > root.data) 
            root.right = create_node(i, root.right); 

        return root;
    }

    public static Node create_bst(int[] arr) {
        Node root = null; 
        for (int i: arr)  
            root = create_node(i, root);
        return root;
