def shift_encrypt(plain_text, shift_count): 
    cipher_text = '' 
    for ch in plain_text:   
        if ch.isalpha(): 
            stayInAlphabet = ord(ch) + shift_count 
            if stayInAlphabet > ord('z'): 
                stayInAlphabet -= 26
            elif stayInAlphabet < ord('a'): 
                stayInAlphabet += 26
            cipher_text += chr(stayInAlphabet)
        else: 
            cipher_text += ch
    return cipher_text

