// A function to create all valid binary trees
// given an array of integers.
// This function generates all possible trees
// by constructing each tree recursively.
def generate_trees(nums):
  // All valid trees will be stored
  // in this list
  valid_trees = []

  // Loop through all elements in the array
  for el in nums:
    # Create a new node
    node = Node(el)

    # Create trees from the subarray left of el
    left_subtrees = generate_trees(nums[:nums.index(el)])

    # Create trees from the subarray right of el
    right_subtrees = generate_trees(nums[nums.index(el) + 1:])

    # Add all possible combinations of
    # left and right subtrees to the list
    for left in left_subtrees:
      node.left = left
      for right in right_subtrees:
        node.right = right
        valid_trees.append(node)

  # Return the list of valid trees
  return valid_trees

