public static int longestSubsequenceLength(int[] arr) 
{ 
    int T[] = new int[arr.length]; 

    // Initializing the arrays 
    for (int i = 0; i < arr.length; i++) 
        T[i] = 1; 

    // Computing the maximum length of 
    // Increasing Subsequence till each 
    // index 
    for (int i = 1; i < arr.length; i++) { 
        for (int j = 0; j < i; j++) { 
            if (arr[i] > arr[j] && T[i] < T[j] + 1) { 
                T[i] = T[j] + 1; 
            } 
        } 
    } 

    // Finding the index with maximum 
    // length 
    int max_idx = 0; 
    for (int i = 0; i < T.length; i++) { 
        if (T[i] > T[max_idx]) { 
            max_idx = i; 
        } 
    } 

    // Returning the maximum length 
    return T[max_idx]; 
}

