// A Java program to determine if two 
// given binary trees are identical 

class Node  
{ 
    int data; 
    Node left, right; 

    Node(int item)  
    { 
        data = item; 
        left = right = null; 
    } 
} 

class BinaryTree  
{ 
    Node root1, root2; 

    /* Given two trees, return true if they are 
       structurally identical */
    boolean identicalTrees(Node a, Node b)  
    { 
        /*1. both empty */
        if (a == null && b == null) 
            return true; 

        /* 2. both non-empty -> compare them */
        if (a != null && b != null)  
        { 
            return (a.data == b.data 
                    && identicalTrees(a.left, b.left) 
                    && identicalTrees(a.right, b.right)); 
        } 

        /* 3. one empty, one not -> false */
        return false; 
    } 
}

def binary_search(array, target):
    left = 0
    right = len(array) - 1
    while left <= right:
        mid = (left + right) // 2
        if array[mid] == target:
            return mid
        elif target < array[mid]:
            right = mid - 1
        else:
            left = mid + 1
    return -1

