    # Converting decimal to its equivalent hexadecimal
    hex_string = ""
    while n > 0:
        remainder = n % 16
        if remainder < 10:
            hex_string += str(remainder)
        else:
            hex_string += chr(remainder + 55)  # Convert number to its equivalent ASCII value
