def serializeTree(root):
    if root is None:
        return ""

    stack = [root]
    output = ""

    while stack:
        node = stack.pop(0)
        output += str(node.data) + ","

        if node.left:
            stack.append(node.left)
        else:
            output += "null,"

        if node.right:
            stack.append(node.right)
        else:
