def binary_search(array, target):
  left = 0
  right = len(array) -1

  while left <= right:
    mid = (left + right) // 2
    current_element = array[mid]
    if current_element == target:
      return mid
    elif target < current_element:
      right = mid -1
    else:
      left = mid + 1

  return -1

