def longest_common_subsequence(list1, list2):
    length1 = len(list1)
    length2 = len(list2)

    tempmax = [[0 for x in range(length2 + 1)] for x in range(length1 + 1)]
    for i in range(length1):
        for j in range(length2):
            if list1[i] == list2[j]:
                tempmax[i + 1][j + 1] = tempmax[i][j] + 1
            else:
                tempmax[i + 1][j + 1] = max(tempmax[i][j + 1], tempmax[i + 1][j])
    maxlength = tempmax[length1][length2]
    result = [None]*maxlength
    x, y = length1, length2
    while x != 0 and y != 0:
        if tempmax[x][y] == tempmax[x - 1][y]:
            x -= 1
        else:
            result[maxlength - 1] = list1[x - 1]
            maxlength -= 1
            y -= 1
            x -= 1
    return result

