def get_max_parts(x):
    # get the product of all elements
    prod = 1
    for i in x:
        prod *= i

    # get the product of all combinations of parts
    ans = 0
    for i in range(1,2**len(x)-1):
        left_prod = 1
        right_prod = 1
        for j in range(len(x)):
            if (i & (1 << j)) > 0:
                left_prod *= x[j]
            else:
                right_prod *= x[j]

        ans = max(ans, left_prod*right_prod)

    # return the result
    return ans

