public class BinarySearchTree<T extends Comparable<T>> {

  private Node<T> root;

  public BinarySearchTree() {
    this.root = null;
  }

  public void insert(T data) {
    if (this.root == null) {
      this.root = new Node<T>(data);
    } else {
      this.root.insert(data);
    }
  }

  public void inorder() {
    if (this.root != null) {
      this.root.inorder();
    }
  }

  public Node<T> search(T data) {
    if (this.root == null) {
      return null;
    }
    return this.root.search(data);
  }

  public void delete(T data) {
    if (this.root != null) {
      this.root = this.root.delete(data);
    }
  }

  private static class Node<T> {
    // Data
    private T data;
    private Node<T> left;
    private Node<T> right;

    public Node(T data) {
      this.data = data;
      this.left = null;
      this.right = null;
    }

    public void insert(T data) {
      if (data.compareTo(this.data) < 0) {
        if (this.left == null) {
          this.left = new Node<T>(data);
        } else {
          this.left.insert(data);
        }
      } else {
        if (this.right == null) {
          this.right = new Node<T>(data);
        } else {
          this.right.insert(data);
        }
      }
    }

    public void inorder() {
      if (this.left != null) {
        this.left.inorder();
      }
      System.out.println(this.data);
      if (this.right != null) {
        this.right.inorder();
      }
    }

    public Node<T> search(T data) {
      if (this.data == data) {
        return this;
      } else if (data.compareTo(this.data) < 0) {
        if (this.left == null) {
          return null;
        } else {
          return this.left.search(data);
        }
      } else {
        if (this.right == null) {
          return null;
        } else {
          return this.right.search(data);
        }
      }
    }

    public Node<T> delete(T data) {
      if (data.compareTo(this.data) < 0) {
        if (this.left != null) {
          this.left = this.left.delete(data);
        }
      } else if (data.compareTo(this.data) > 0) {
        if (this.right != null) {
          this.right = this.right.delete(data);
        }
      } else {
        // Node contains data
        if (this.left == null && this.right == null) {
          // Leaf Node
          return null;
        } else if (this.left == null) {
          // Single right child
          return this.right;
        } else if (this.right == null) {
          // Single left child
          return this.left;
        } else {
          // Two children
          Node<T> minNode = this.right.minNode();
          this.data = minNode.data;
          this.right = this.right.delete(minNode.data);
        }
      }

      return this;
    }

    public Node<T> minNode() {
      if (this.left == null) {
        return this;
      } else {
        return this.left.minNode();
      }
    }
  }
}

void quickSort(int arr[], int left, int right) {
        int i = left, j = right;
        int tmp;
        int pivot = arr[(left + right) / 2];

        /* partition */
        while (i <= j) {
            while (arr[i] < pivot)
                i++;
            while (arr[j] > pivot)
                j--;
            if (i <= j) {
                tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
                i++;
                j--;
            }
        };

        /* recursion */
        if (left < j)
            quickSort(arr, left, j);
        if (i < right)
            quickSort(arr, i, right);
}

