class AVL_Tree:

    def insert(self, root, key):

        # Step 1 - Perform normal BST
        if not root:
            return Node(key)
        elif key < root.data:
            root.left = self.insert(root.left, key)
        else:
            root.right = self.insert(root.right, key)

        # Step 2 - Update the height of the
        # ancestor node
        root.height = 1 + max(self.getHeight(root.left),
                           self.getHeight(root.right))

        # Step 3 - Get the balance factor
        balance = self.getBalance(root)

        # Step 4 - If the node is unbalanced,
        # then try out the 4 cases
        # Case 1 - Left Left
        if balance > 1 and key < root.left.data:
            return self.rightRotate(root)

        # Case 2 - Right Right
        if balance < -1 and key > root.right.data:
            return self.leftRotate(root)

        # Case 3 - Left Right
        if balance > 1 and key > root.left.data:
            root.left = self.leftRotate(root.left)
            return self.rightRotate(root)

        # Case 4 - Right Left
        if balance < -1 and key < root.right.data:
            root.right = self.rightRotate(root.right)
            return self.leftRotate(root)

        return root

    def leftRotate(self, z):

        y = z.right
        T2 = y.left

        # Perform rotation
        y.left = z
        z.right = T2

        # Update heights
        z.height = 1 + max(self.getHeight(z.left),
                         self.getHeight(z.right))
        y.height = 1 + max(self.getHeight(y.left),
                         self.getHeight(y.right))

        # Return the new root
        return y

    def rightRotate(self, z):

        y = z.left
        T3 = y.right

        # Perform rotation
        y.right = z
        z.left = T3

        # Update heights
        z.height = 1 + max(self.getHeight(z.left),
                        self.getHeight(z.right))
        y.height = 1 + max(self.getHeight(y.left),
                        self.getHeight(y.right))

        # Return the new root
        return y

    def getHeight(self, root):
        if not root:
            return 0

        return root.height

    def getBalance(self, root):
        if not root:
            return 0

        return self.getHeight(root.left) - self.getHeight(root.right)

    def preOrder(self, root):

        if not root:
            return

        # First print the data of node
        print("{0} ".format(root.data), end="")

        # Then recur on left child
        self.preOrder(root.left)

        # Finally recur on right child
        self.preOrder(root.right)

public class BalancedParentheses 
{
    // Method to check if parantheses are balanced 
    static boolean areBalanced(String inputString) 
    {
        // Declaring a stack 
        Stack<Character> stack = new Stack<Character>(); 

        // Traversing the Expression 
        for (int i = 0; i < inputString.length(); i++) 
        { 
            if (inputString.charAt(i) == '(' || inputString.charAt(i) == '{' || inputString.charAt(i) == '[') 
            { 
                // Push the element in the stack 
                stack.push(inputString.charAt(i)); 
            } 
            else if (inputString.charAt(i) == ')'|| inputString.charAt(i) == '}' || inputString.charAt(i) == ']') 
            { 
                // IF current character is not opening 
                // bracket, then it must be closing. 
                // So stack cannot be empty at this point. 
                if (stack.isEmpty()) 
                    return false; 

                // Pop the top element from stack, if 
                // it is not a pair parenthesis of character 
                // then there is a mismatch. 
                char top = stack.pop(); 

                if (inputString.charAt(i) == ')' && top!='(' || inputString.charAt(i) == '}' && top!='{' || inputString.charAt(i) == ']' && top!='[') 
                    return false; 
            } 
        } 

        // Check Empty Stack 
        return (stack.isEmpty()); 
    } 

    // main method 
    public static void main (String[] args) 
    { 
        String inputString; 
        inputString = "{(())}"; 
        boolean result = areBalanced(inputString); 
	if(result == true) 
            System.out.println("Balanced Parenthesis"); 
        else
            System.out.println("Not Balanced Parenthesis");  
    } 
}

