        let firstChar = str[i];
        let remainder = str.substring(0, i) + str.substring(i + 1);
        let innerPermutations = permutations(remainder);
        for (let j = 0; j < innerPermutations.length; j++) {
            results.push(firstChar + innerPermutations[j]);
        } 
    }
    return results;
}

