def minimumWeightPath(grid):
    x = len(grid[0])
    y = len(grid)
    dp = [[float('inf') for i in range(x)] for j in range(y)] 
    dp[0][0] = grid[0][0] 
    for i in range(1, x): 
        dp[0][i] = dp[0][i-1] + grid[0][i] 
    for j in range(1, y): 
        dp[j][0] = dp[j-1][0] + grid[j][0] 
    for i in range(1, y):
        for j in range(1, x):
            dp[i][j] = min(dp[i-1][j], 
                      dp[i][j-1]) + grid[i][j] 
    return dp[y-1][x-1]

