def lcs(str1, str2):
  # create a 2D array filled with all 0s
  dp = [[0 for _ in range(len(str1)+1)] for _ in range(len(str2)+1)]

  # fill the dp  array
  for i in range(1, len(str2) + 1):
      for j in range(1, len(str1) + 1):
          if str2[i-1] == str1[j-1]:
             dp[i][j] = dp[i-1][j-1] + 1
          else:
              dp[i][j] = max(dp[i-1][j], dp[i][j-1])

  # backtrack the dp array and reconstruct the LCS
  lcs_string = ""
  i, j = len(str2), len(str1)
  while i >= 0 and j >= 0:
      if str2[i-1] == str1[j-1]:
         lcs_string += str2[i-1]
         i -= 1
         j -= 1
      elif dp[i-1][j] > dp[i][j-1]:
          i -= 1
      else:
          j -= 1

  return lcs_string[::-1]

