public ListNode treeToList(TreeNode root) {
    if (root == null)
        return null;

    ListNode head = null;
    ListNode tail = null;

    Stack<TreeNode> stack = new Stack<>();
    stack.push(root);

    while (!stack.isEmpty()) {
        TreeNode node = stack.pop();

        if (node != null) {
            ListNode currentNode = new ListNode(node.val);

            if (head == null)
                head = currentNode;
            else
                tail.next = currentNode;

            tail = currentNode;
            stack.push(node.right);
            stack.push(node.left);
        }
    }
    return head;
}

