import numpy as np 
import time 

# Helper function to initialize a two dimensional array
def get_matrix(x, y):
    matrix = [[0 for i in range(x)] for j in range(y)]
    return matrix

# Function which performs a single iteration of the game
def iterate(board):
    # Make a copy to keep track of changes
    new_board = board.copy()

    for i in range(board.shape[0]):
        for j in range(board.shape[1]):
            neighbors = get_neighbors(board, i, j)
            n_live_neighbors = get_live_neighbors(neighbors)
            if board[i][j]== 0 and n_live_neighbors ==3:
                new_board[i][j] = 1
            elif board[i][j] == 1 and (n_live_neighbors > 3 or n_live_neighbors < 2):
                new_board[i][j] = 0
            else:
                pass
    board = new_board

    print_board(board)
    print()

    return board 

# Neighbors is the 8 adjacent fields in the board
def get_neighbors(board, row, col):
    neighbors = []
    for i in range(-1,2):
        for j in range(-1,2):
            if(i == 0 and j == 0):
                pass
            # This check will prevent index out of bounds error
            elif row + i >= 0 and row + i < board.shape[0] and col + j >= 0 and col + j < board.shape[1]:
                neighbors.append(board[row+i][col+j])
    return neighbors

# Count the number of live neighbors
def get_live_neighbors(neighbors):
    n_live_neighbors = 0
    for n in neighbors:
        if n == 1:
            n_live_neighbors += 1
    return n_live_neighbors

# Print the board
def print_board(board):
    for row in board:
        print(row)

# Main function to run the simulation
def run_simulation(x, y, steps):
    board = get_matrix(x, y)
    for step in range(steps):
        board = iterate(board)
        time.sleep(1)

