def evaluate_expression(exp, env):

    # Split the expression into components
    components = exp.split()
    i = 0
    while i < len(components):
        component = components[i]
        # If the component is a variable, replace it with its value in the environment
        if component in env:
            components[i] = str(env[component])
        i+=1
    # Join the components back together and evaluate the expression
    exp = "".join(components) 
    return eval(exp)

