def LCS(x, y):
    m = len(x)
    n = len(y)

    dp = [[None]*(n+1) for i in range(m+1)]

    # Initialize first column of the matrix as 0 
    for i in range(m+1): 
        dp[i][0] = 0

    # Initialize first row of the matrix as 0 
    for j in range(n+1): 
        dp[0][j] = 0

    # Fill the dp matrix 
    for i in range(1, m+1): 
        for j in range(1, n+1): 
            if x[i-1] == y[j-1]: 
                dp[i][j] = 1 + dp[i-1][j-1] 

            else: 
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) 

    return dp[m][n]

