    l = len(integers) 
    nodes = [root] 
    while (i < l):  
        node = nodes.pop(0)  

        if (2 * i + 1 < l and integers[2 * i + 1] is not None): 
            node.left = TreeNode(integers[2 * i + 1])  
            nodes.append(node.left)  

        if (2 * i + 2 < l and integers[2 * i + 2] is not None): 
            node.right = TreeNode(integers[2 * i + 2])  
            nodes.append(node.right)  

        i += 1

    return root

