fn fokuss_sort(v: &mut [i32]) {
    let mut max: i32 = 0;
    let mut min: i32 = std;
    for x in v {
        max = std::cmp::max(max, *x);
        min = std::cmp::min(min, *x);
    }

    let mut i = min;
    let mut j = max;
    while i < j {
        while i < j && v[i as usize] == i {
            i += 1;
        }
        while i < j && v[j as usize] > j {
            j -= 1;
        }
        if i < j {
            v.swap(i as usize, j as usize);
        }
    }
}

