function findMiddleElement(head) {
    if (head == null || head.next == null) {
        return head;
    }

    let slow = head;
    let fast = head.next;

    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
    }

    return slow.val;
}

