func evaluateExpression(expression: String) -> Int {
 let expressionSplit = expression.split(separator: " ")

 var total = 0
 var operator: Character?
 var previousOperand = 0

 for part in expressionSplit {
 let partString = String(part)

 if let intValue = Int(partString) {
 if let op = operator {
 switch op {
 case "+": total = previousOperand + intValue
 case "-": total = previousOperand - intValue
 case "*": total = previousOperand * intValue
 case "/": total = previousOperand / intValue
 default: break
 }
 } else {
 total = intValue
 }

 previousOperand = intValue
 } else if let op = partString.first {
 operator = op
 }
 }

 return total
}

