        self.name = name
        self.children = []

    def add_child(self, node):
        self.children.append(node)

    def depth_first_search(node): 
        visited = []
        stack = [node]
        while len(stack) > 0:
            node = stack.pop()
            visited.append(node)
            for child in node.children:
                if child not in visited:
                    stack.append(child)
        return visited

